module rrt_tree (
    input clk,
    input rst,
    input [7:0] start_x,
    input [7:0] start_y,
    input [7:0] goal_x,
    input [7:0] goal_y,
    input [7:0] rand_x,
    input [7:0] rand_y,
    output reg [7:0] tree_x,
    output reg [7:0] tree_y,
    output reg done
);
    parameter MAX_ITER = 5;
    parameter DIST_THRESH = 10;

    reg [3:0] iter; // iteration counter

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tree_x <= start_x;
            tree_y <= start_y;
            iter <= 0;
            done <= 0;
        end else if (iter < MAX_ITER) begin
            if ((rand_x - tree_x) * (rand_x - tree_x) + (rand_y - tree_y) * (rand_y - tree_y) <= DIST_THRESH * DIST_THRESH) begin
                tree_x <= rand_x;
                tree_y <= rand_y;
                iter <= iter + 1;
                if (iter + 1 == MAX_ITER) begin
                    done <= 1; // Tree growth done after max iterations
                end
            end
        end
    end
endmodule

