module ofdm_modulator(
    input wire clk,
    input wire reset,
    input wire [15:0] bits,
    output reg [15:0] time_domain_signal
);
    reg [15:0] subcarriers [0:15];
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            time_domain_signal <= 16'b0;
        end else begin
            // Map input bits to subcarriers
            for (i = 0; i < 16; i = i + 1) begin
                subcarriers[i] <= bits[i] ? 16'h1 : 16'h0; // Map bit to signal
            end

            // Compute IFFT (simplified as a sum for this example)
            time_domain_signal <= 16'b0;
            for (i = 0; i < 16; i = i + 1) begin
                time_domain_signal <= time_domain_signal + subcarriers[i];
            end
        end
    end
endmodule

