module ecc_point_add (
    input clk,
    input rst,
    input [7:0] x1,
    input [7:0] y1,
    input [7:0] x2,
    input [7:0] y2,
    output reg [7:0] x3,
    output reg [7:0] y3
);

    reg [7:0] lambda;
    reg [7:0] x3_temp;
    reg [7:0] y3_temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x3 <= 8'b0;
            y3 <= 8'b0;
        end else begin
            // Calculate lambda = (y2 - y1) / (x2 - x1)
            if (x2 != x1) begin
                lambda <= (y2 - y1) / (x2 - x1);
                // Calculate x3 = lambda^2 - x1 - x2
                x3_temp <= (lambda * lambda) - x1 - x2;
                // Calculate y3 = lambda * (x1 - x3) - y1
                y3_temp <= (lambda * (x1 - x3_temp)) - y1;
                x3 <= x3_temp;
                y3 <= y3_temp;
            end
        end
    end
endmodule

