module spi_master (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg mosi,
    output reg done
);
    reg [2:0] state;
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    localparam IDLE = 3'b000,
               START = 3'b001,
               SEND = 3'b010,
               DONE = 3'b011;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    shift_reg <= data_in;
                    bit_count <= 3'b000;
                    state <= START;
                end
            end
            START: begin
                state <= SEND;
            end
            SEND: begin
                if (bit_count < 8) begin
                    mosi <= shift_reg[7]; // send the MSB first
                    shift_reg <= {shift_reg[6:0], 1'b0}; // shift left
                    bit_count <= bit_count + 1;
                end else begin
                    state <= DONE;
                end
            end
            DONE: begin
                mosi <= 1'b0; // in case we want to keep MOSI low after transmission
                done <= 1;
                state <= IDLE; // reset to IDLE state
            end
        endcase
    end
endmodule

