module uart_controller (  
    input clk,  
    input reset,  
    input start,  
    input [7:0] data_in,  
    output reg tx,  
    output reg ready  
);  

    reg [3:0] bit_count;  
    reg [7:0] shift_reg;  
    reg transmitting;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            tx <= 1;  
            ready <= 1;  
            transmitting <= 0;  
            bit_count <= 0;  
        end else if (start && ready) begin  
            shift_reg <= data_in;  
            bit_count <= 0;  
            tx <= 0; // Start bit  
            transmitting <= 1;  
            ready <= 0;  
        end else if (transmitting) begin  
            if (bit_count < 8) begin  
                tx <= shift_reg[0];  
                shift_reg <= {1'b0, shift_reg[7:1]}; // Shift left  
                bit_count <= bit_count + 1;  
            end else begin  
                tx <= 1; // Stop bit  
                transmitting <= 0;  
                ready <= 1;  
            end  
        end  
    end  
endmodule

