module uart_tx(
    input wire clk,
    input wire rst,
    input wire start_tx,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600; // Set Baud Rate
    parameter CLOCK_FREQ = 50000000; // Set Clock Frequency
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_count;
    reg [15:0] clk_count;
    reg [7:0] shift_reg;
    reg state; // 0: idle, 1: transmitting

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state
            busy <= 0;
            bit_count <= 0;
            clk_count <= 0;
            state <= 0;
        end else begin
            if (state == 0 && start_tx) begin
                shift_reg <= data_in;
                tx <= 0; // Start bit
                busy <= 1;
                bit_count <= 0;
                clk_count <= 0;
                state <= 1;
            end else if (state == 1) begin
                if (clk_count < BIT_PERIOD - 1) begin
                    clk_count <= clk_count + 1;
                end else begin
                    clk_count <= 0;
                    if (bit_count < 8) begin
                        tx <= shift_reg[bit_count]; // Send data bits
                        bit_count <= bit_count + 1;
                    end else if (bit_count == 8) begin
                        tx <= 1; // Stop bit
                        bit_count <= bit_count + 1;
                    end else begin
                        tx <= 1; // Idle state
                        busy <= 0;
                        state <= 0; // Back to idle
                    end
                end
            end
        end
    end
endmodule

