module non_restoring_divider (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [3:0] state;
    reg [15:0] A; // Accumulator
    reg [7:0] Q;  // Quotient
    reg [7:0] M;  // Divisor
    reg [3:0] count;

    parameter IDLE = 4'b0000;
    parameter LOAD = 4'b0001;
    parameter SHIFT = 4'b0010;
    parameter SUB = 4'b0011;
    parameter ADD = 4'b0100;
    parameter DONE = 4'b0101;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            quotient <= 0;
            remainder <= 0;
            done <= 0;
            A <= 0;
            Q <= 0;
            M <= 0;
            count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        A <= {dividend, 8'b0}; // Load dividend
                        M <= divisor; // Load divisor
                        Q <= 0; // Initialize quotient
                        count <= 8; // Set count for 8 bits
                        state <= LOAD;
                    end
                end

                LOAD: begin
                    if (count > 0) begin
                        state <= SHIFT;
                    end else begin
                        state <= DONE;
                        quotient <= Q;
                        remainder <= A[7:0];
                        done <= 1;
                    end
                end

                SHIFT: begin
                    A <= {A[14:0], Q[7]}; // Shift left A and Q
                    Q <= {Q[6:0], 1'b0}; // Shift left Q
                    state <= SUB;
                end

                SUB: begin
                    A = A - {M, 8'b0}; // Subtract M from A
                    if (A[15] == 1) begin // If negative
                        A = A + {M, 8'b0}; // Add M back to A
                        Q[0] <= 0; // Set least significant bit of Q to 0
                    end else begin
                        Q[0] <= 1; // Set least significant bit of Q to 1
                    end
                    count <= count - 1; // Decrement count
                    state <= LOAD; // Go back to LOAD state
                end

                DONE: begin
                    done <= 1; // Indicate done state
                end
            endcase
        end
    end
endmodule

