module pulse_generator(
    input clk,
    input reset,
    input enable,
    input [7:0] pulse_width,
    input [7:0] pulse_period,
    output reg pulse_out
);
    reg [7:0] counter;
    reg [7:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            pulse_out <= 0;
            state <= 0;
        end else if (enable) begin
            if (state < pulse_period) begin
                if (counter < pulse_width) begin
                    pulse_out <= 1;
                    counter <= counter + 1;
                end else begin
                    pulse_out <= 0;
                    counter <= counter + 1;
                end
                state <= state + 1;
            end else begin
                state <= 0;
                counter <= 0;
            end
        end else begin
            pulse_out <= 0;
            counter <= 0;
            state <= 0;
        end
    end
endmodule

