module phase_detector(
    input clk_a,
    input clk_b,
    output reg phase_out
);
    reg a_prev, b_prev;

    always @(posedge clk_a or posedge clk_b) begin
        if (clk_a) begin
            a_prev <= 1;
        end else begin
            a_prev <= 0;
        end

        if (clk_b) begin
            b_prev <= 1;
        end else begin
            b_prev <= 0;
        end

        // Phase detection logic
        if (a_prev && !b_prev) begin
            phase_out <= 1; // clk_a is leading
        end else if (!a_prev && b_prev) begin
            phase_out <= 0; // clk_b is leading
        end
    end
endmodule

