module bubble_sort (
    input wire clk,
    input wire start,
    input wire [15:0] data_in, // 4 numbers, 4 bits each
    output reg [15:0] data_out, // sorted output
    output reg done
);
    reg [3:0] arr [0:3]; // array of 4 elements
    reg [1:0] i, j;
    reg sorting;

    always @(posedge clk) begin
        if (start) begin
            arr[0] <= data_in[15:12];
            arr[1] <= data_in[11:8];
            arr[2] <= data_in[7:4];
            arr[3] <= data_in[3:0];
            i <= 0;
            j <= 0;
            sorting <= 1;
            done <= 0;
        end else if (sorting) begin
            if (i < 3) begin
                if (j < 3 - i) begin
                    if (arr[j] > arr[j + 1]) begin
                        // Swap
                        {arr[j], arr[j + 1]} <= {arr[j + 1], arr[j]};
                    end
                    j <= j + 1;
                end else begin
                    j <= 0;
                    i <= i + 1;
                end
            end else begin
                sorting <= 0;
                done <= 1;
                data_out <= {arr[0], arr[1], arr[2], arr[3]};
            end
        end
    end
endmodule

