module kalman_filter (
    input clk,
    input reset,
    input [15:0] measurement,  // noisy position measurement
    output reg [15:0] pos_est,  // estimated position
    output reg [15:0] vel_est   // estimated velocity
);
    // Kalman filter parameters (these would typically be tuned)
    reg [15:0] K_pos = 16'h0A;  // Kalman gain for position
    reg [15:0] K_vel = 16'h0B;  // Kalman gain for velocity
    reg [15:0] pos_prev = 16'h0; // previous position estimate
    reg [15:0] vel_prev = 16'h0; // previous velocity estimate

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pos_est <= 16'h0;
            vel_est <= 16'h0;
            pos_prev <= 16'h0;
            vel_prev <= 16'h0;
        end else begin
            // Update estimates
            pos_est <= pos_prev + vel_prev + K_pos * (measurement - pos_prev);
            vel_est <= vel_prev + K_vel * (measurement - pos_prev);
            // Update previous estimates
            pos_prev <= pos_est;
            vel_prev <= vel_est;
        end
    end
endmodule

