module lzw_compressor(input clk,  
                      input reset,  
                      input [7:0] data_in,  
                      input valid_in,  
                      output reg [15:0] code_out,  
                      output reg valid_out);  

    reg [7:0] dict [0:255];  
    reg [15:0] codes [0:255];  
    integer dict_size;  
    integer i;  
    reg [7:0] current_symbol;  
    reg [15:0] current_code;  

    initial begin  
        dict_size = 0;  
        for (i = 0; i < 256; i = i + 1) begin  
            dict[i] = i;  
            codes[i] = i;  
        end  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            dict_size <= 0;  
            valid_out <= 0;  
        end else if (valid_in) begin  
            current_symbol <= data_in;  
            // Simplified LZW logic: just output the symbol code for now  
            current_code <= codes[current_symbol];  
            code_out <= current_code;  
            valid_out <= 1;  
        end else begin  
            valid_out <= 0;  
        end  
    end  
endmodule

