module rsa_encrypt (
    input wire clk,
    input wire reset,
    input wire [31:0] plaintext,
    input wire [31:0] e,
    input wire [31:0] n,
    output reg [31:0] ciphertext
);
    reg [31:0] temp_result;
    reg [5:0] bit_count; // To count bits of exponent

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ciphertext <= 32'b0;
            temp_result <= 32'b1; // Identity for multiplication
            bit_count <= 6'b0;
        end else begin
            if (bit_count < 32) begin
                if (e[bit_count]) begin
                    temp_result <= (temp_result * plaintext) % n;
                end
                ciphertext <= (temp_result % n);
                bit_count <= bit_count + 1;
            end
        end
    end
endmodule

